```c
void run_freeze_thaw_test(uint32_t target_cycles) {
float T_min = -40.0f;
float T_max = 80.0f;
uint32_t dwell_time_min = 120;  // 2 hours


for (uint32_t cycle = 0; cycle < target_cycles; cycle++) {
