    Rte_Write_ActuatorCluster_CurrentGear(current_gear);
    Rte_Write_ActuatorCluster_TorqueConverterState(tc_state);
    Rte_Write_CAN_TorqueReductionRequest(shift_in_progress ? 30.0f : 0.0f);
}
