}

IntersectionGeometry ::= SEQUENCE {
    name DescriptiveName OPTIONAL,
    id IntersectionReferenceID,
    revision MsgCount,
    refPoint Position3D,
    laneWidth LaneWidth OPTIONAL,
    speedLimits SpeedLimitList OPTIONAL,
    laneSet LaneList,
