# GraphQL for Vehicle Data

Expert guidance for building flexible vehicle data APIs using GraphQL with AWS AppSync, Azure Data API Builder, and Apollo Server for efficient fleet management queries.

## Architecture Overview

```
Mobile/Web Clients
       |
       v
GraphQL API (Query, Mutation, Subscription)
       |
       v
Resolvers (Lambda, Functions, Microservices)
       |
       v
Data Sources (DynamoDB, Cosmos, SQL, REST APIs)
```

**GraphQL Benefits for Automotive**:
- Single endpoint for all vehicle data
- Client-specified response shape
- Real-time subscriptions for telemetry
- Efficient batching and caching
- Strong typing and introspection
- Reduced over/under-fetching

## Schema Design

### Core Types

```graphql
# schema.graphql

"""
Vehicle identification and core details
"""
type Vehicle {
  vin: String!
  model: String!
  year: Int!
  batteryCapacityKwh: Float!
  softwareVersion: String!
  lastConnected: AWSDateTime!

  # Nested queries
  telemetry(
    from: AWSDateTime
    to: AWSDateTime
    limit: Int = 100
  ): TelemetryConnection!

  diagnostics(
    severity: [DiagnosticSeverity!]
    resolved: Boolean
  ): [DiagnosticCode!]!

  trips(
    from: AWSDateTime
    to: AWSDateTime
  ): [Trip!]!

  currentState: VehicleState!
  config: VehicleConfig!
}

"""
Real-time telemetry data
"""
type TelemetryData {
  timestamp: AWSDateTime!
  batteryVoltageV: Float!
  batteryCurrentA: Float!
  batteryTempC: Float!
  batterySocPct: Float!
  speedKmh: Float
  location: Location
  odometerkm: Float
}

"""
Paginated telemetry response
"""
type TelemetryConnection {
  items: [TelemetryData!]!
  nextToken: String
  count: Int!
}

"""
Diagnostic trouble code
"""
type DiagnosticCode {
  id: ID!
  vin: String!
  dtcCode: String!
  severity: DiagnosticSeverity!
  description: String!
  system: VehicleSystem!
  timestamp: AWSDateTime!
  resolved: Boolean!
  resolvedAt: AWSDateTime
}

enum DiagnosticSeverity {
  CRITICAL
  HIGH
  MEDIUM
  LOW
}

enum VehicleSystem {
  POWERTRAIN
  CHASSIS
  BODY
  NETWORK
  BATTERY
}

"""
Vehicle state information
"""
type VehicleState {
  state: State!
  chargingState: ChargingState
  location: Location
  isMoving: Boolean!
  lastUpdated: AWSDateTime!
}

enum State {
  PARKED
  DRIVING
  CHARGING
  OFFLINE
}

enum ChargingState {
  IDLE
  CHARGING
  COMPLETE
  ERROR
}

"""
Geographic location
"""
type Location {
  latitude: Float!
  longitude: Float!
  accuracy: Float
  timestamp: AWSDateTime!
}

"""
Trip information
"""
type Trip {
  id: ID!
  vin: String!
  startTime: AWSDateTime!
  endTime: AWSDateTime
  startLocation: Location!
  endLocation: Location
  distanceKm: Float
  energyConsumedKwh: Float
  averageSpeedKmh: Float
  maxSpeedKmh: Float
}

"""
Vehicle configuration
"""
type VehicleConfig {
  chargeLimitPct: Float!
  maxChargeCurrentA: Float!
  preconditioningEnabled: Boolean!
  regenerativeBrakingLevel: Int!
}

"""
Fleet-wide statistics
"""
type FleetStats {
  totalVehicles: Int!
  onlineVehicles: Int!
  chargingVehicles: Int!
  averageSocPct: Float!
  totalEnergyConsumedKwh: Float!
  totalDistanceKm: Float!
}

# Query root
type Query {
  """
  Get vehicle by VIN
  """
  vehicle(vin: String!): Vehicle

  """
  List vehicles with filtering
  """
  vehicles(
    state: State
    minSoc: Float
    maxSoc: Float
    limit: Int = 20
    nextToken: String
  ): VehicleConnection!

  """
  Get fleet statistics
  """
  fleetStats: FleetStats!

  """
  Search vehicles by location
  """
  vehiclesByLocation(
    latitude: Float!
    longitude: Float!
    radiusKm: Float!
  ): [Vehicle!]!
}

type VehicleConnection {
  items: [Vehicle!]!
  nextToken: String
  count: Int!
}

# Mutation root
type Mutation {
  """
  Update vehicle configuration
  """
  updateVehicleConfig(
    vin: String!
    config: VehicleConfigInput!
  ): VehicleConfig!

  """
  Send remote command to vehicle
  """
  sendCommand(
    vin: String!
    command: VehicleCommand!
    parameters: AWSJSON
  ): CommandResponse!

  """
  Mark diagnostic code as resolved
  """
  resolveDiagnostic(
    vin: String!
    dtcCode: String!
  ): DiagnosticCode!
}

input VehicleConfigInput {
  chargeLimitPct: Float
  maxChargeCurrentA: Float
  preconditioningEnabled: Boolean
  regenerativeBrakingLevel: Int
}

enum VehicleCommand {
  START_CHARGING
  STOP_CHARGING
  PRECONDITION
  LOCK
  UNLOCK
  HONK
  FLASH_LIGHTS
}

type CommandResponse {
  success: Boolean!
  message: String
  requestId: String!
}

# Subscription root
type Subscription {
  """
  Subscribe to telemetry updates for a vehicle
  """
  onTelemetryUpdate(vin: String!): TelemetryData
    @aws_subscribe(mutations: ["publishTelemetry"])

  """
  Subscribe to vehicle state changes
  """
  onVehicleStateChange(vin: String!): VehicleState
    @aws_subscribe(mutations: ["updateVehicleState"])

  """
  Subscribe to new diagnostic codes
  """
  onDiagnosticDetected(vin: String!): DiagnosticCode
    @aws_subscribe(mutations: ["reportDiagnostic"])
}

# Internal mutation for publishing telemetry
type Mutation {
  publishTelemetry(
    vin: String!
    data: TelemetryInput!
  ): TelemetryData
}

input TelemetryInput {
  timestamp: AWSDateTime!
  batteryVoltageV: Float!
  batteryCurrentA: Float!
  batteryTempC: Float!
  batterySocPct: Float!
  speedKmh: Float
  location: LocationInput
}

input LocationInput {
  latitude: Float!
  longitude: Float!
  accuracy: Float
}
```

